BlocklyGamesMsg["Music.submitDisabled"] = "ፕሮግራምዎ እስኪያቆም ድረስ ያሂዱ። ከዚያ ስዕልዎን ወደ ቤተ-ስዕሉ ማስገባት ይችላሉ።";
BlocklyGamesMsg["Music.galleryTooltip"] = "የሙዚቃ ማእከልን ይክፈቱ።";
